/*
	VIOC_civilians.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "civ_people": civiles locales (agentes) que caminan por los pueblos cercanos al jugador.

	- Solo corre en el servidor (en una partida alojada, tu PC). En los clientes no hace nada.
	- Un pueblo se llena cuando un jugador esta a <= 900 m y se vacia cuando todos estan a > 1300 m
	  (y lleva al menos 60 s activo). No se reponen los muertos hasta que el pueblo se vacia.
	- 4 / 6 / 8 civiles segun el tamano del pueblo (cti_town_maxSV 60 / 90 / 120), la mitad de noche,
	  tope global 40. Modo "Mas": 6 / 9 / 12, tope 60.
	- Son agentes (createAgent) del lado civilian y sin armas. La mision solo cuenta west, east y
	  resistance (countSide) para captura, campamentos, activacion de pueblos, morteros e ingresos, y las
	  recompensas solo existen para las unidades que crea la mision; los civiles no tocan nada de eso.
	- Caminan entre calles y plantas bajas de casas. Si oyen disparos a menos de ~70 m, reciben un
	  impacto o matan a alguien a su lado, corren a la casa mas cercana y se agachan de 40 a 80 s.
	- Esperan y aparecen al costado de las calles, no sobre el asfalto. Si un defensor de pueblo o un mortero mata
	  civiles, su rating vuelve a 0 para que no quede renegado. Volar alto no llena pueblos, pero tampoco los vacia.
	- Parametro de lobby VIOC_CIV_PEOPLE: 0 = apagado, 1 = normal (por defecto), 2 = mas.
	- Consola de depuracion: VIOC_CIVP_STATUS = [pueblos activos, civiles vivos];
	  VIOC_CIVP_DEBUG = true muestra en el chat cada pueblo que se llena o se vacia.
*/
if (!isServer) exitWith {};

private _mode = missionNamespace getVariable ["VIOC_CIV_PEOPLE", 1];
if !(_mode isEqualType 0) then {_mode = 1};
if (_mode <= 0) exitWith {diag_log "VIOC_civilians: desactivado (parametro de lobby VIOC_CIV_PEOPLE = 0)."};

waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Towns"}};
waitUntil {sleep 2; missionNamespace getVariable ["CTI_Server_Loaded", false]};
sleep 15;

//--- Ajustes
VIOC_CIVP_SPAWN_DIST = 900;     // un jugador a esta distancia (m) llena el pueblo
VIOC_CIVP_DESPAWN_DIST = 1300;  // si todos los jugadores estan mas lejos, se vacia
VIOC_CIVP_MIN_LIFE = 60;        // segundos minimos que un pueblo queda lleno (evita parpadeo)
VIOC_CIVP_AIR_IGNORE = 150;     // jugadores volando a mas de 150 m de altura no llenan pueblos
VIOC_CIVP_CAP = [40, 60] select (_mode >= 2);
VIOC_CIVP_MULT = [1, 1.5] select (_mode >= 2);
VIOC_CIVP_NIGHT_MULT = 0.5;     // de noche (antes de las 5 o despues de las 19) la mitad
VIOC_CIVP_DEBUG = false;
//--- Pueblos que en realidad son sitios militares o industriales (se comparan en minusculas).
//--- "camp", "air station", "outpost" y "kill farm" son para Stratis (Camp Maxwell/Tempest/Rogan, Air Station Mike-26, Outpost, Kill Farm).
VIOC_CIVP_EXCLUDE = ["military", "base", "airport", "aeroport", "aerodrome", "airfield", "airstrip", "radio", "comms", "range", "arty", "power", "mine", "depot", "lumber", "dump", "camp", "air station", "outpost", "kill farm"];
VIOC_CIVP_HOUSE_TYPES = ["HOUSE", "BUILDING", "CHURCH", "CHAPEL", "HOSPITAL", "FUELSTATION"];

//--- Clases por region (CUP primero; se filtran con isClass, asi que sin CUP se usan las vanilla)
private _cupCher = [
	"CUP_C_C_Citizen_01", "CUP_C_C_Citizen_02", "CUP_C_C_Citizen_03", "CUP_C_C_Citizen_04",
	"CUP_C_C_Villager_01", "CUP_C_C_Villager_02", "CUP_C_C_Villager_03", "CUP_C_C_Villager_04",
	"CUP_C_C_Woodlander_01", "CUP_C_C_Woodlander_02", "CUP_C_C_Woodlander_03", "CUP_C_C_Woodlander_04",
	"CUP_C_C_Worker_01", "CUP_C_C_Worker_02", "CUP_C_C_Worker_03", "CUP_C_C_Worker_04", "CUP_C_C_Worker_05",
	"CUP_C_C_Mechanic_01", "CUP_C_C_Mechanic_02", "CUP_C_C_Mechanic_03",
	"CUP_C_C_Profiteer_01", "CUP_C_C_Profiteer_02", "CUP_C_C_Profiteer_03", "CUP_C_C_Profiteer_04",
	"CUP_C_C_Racketeer_01", "CUP_C_C_Racketeer_02", "CUP_C_C_Racketeer_03", "CUP_C_C_Racketeer_04",
	"CUP_C_C_Rocker_01", "CUP_C_C_Rocker_02", "CUP_C_C_Rocker_03", "CUP_C_C_Rocker_04",
	"CUP_C_C_Bully_01", "CUP_C_C_Bully_02", "CUP_C_C_Bully_03", "CUP_C_C_Bully_04",
	"CUP_C_C_Functionary_01", "CUP_C_C_Functionary_02", "CUP_C_C_Functionary_jacket_01",
	"CUP_C_C_Functionary_jacket_02", "CUP_C_C_Functionary_jacket_03", "CUP_C_C_Schoolteacher_01", "CUP_C_C_Priest_01"
];
private _cupTK = [
	"CUP_C_TK_Man_01_Coat", "CUP_C_TK_Man_01_Jack", "CUP_C_TK_Man_01_Waist",
	"CUP_C_TK_Man_02", "CUP_C_TK_Man_02_Jack", "CUP_C_TK_Man_02_Waist",
	"CUP_C_TK_Man_03_Coat", "CUP_C_TK_Man_03_Jack", "CUP_C_TK_Man_03_Waist",
	"CUP_C_TK_Man_04", "CUP_C_TK_Man_04_Jack", "CUP_C_TK_Man_04_Waist",
	"CUP_C_TK_Man_05_Coat", "CUP_C_TK_Man_05_Jack", "CUP_C_TK_Man_05_Waist",
	"CUP_C_TK_Man_06_Coat", "CUP_C_TK_Man_06_Jack", "CUP_C_TK_Man_06_Waist",
	"CUP_C_TK_Man_07", "CUP_C_TK_Man_07_Coat", "CUP_C_TK_Man_07_Waist",
	"CUP_C_TK_Man_08", "CUP_C_TK_Man_08_Jack", "CUP_C_TK_Man_08_Waist"
];
private _vanMed = [
	"C_man_1", "C_man_1_1_F", "C_man_1_2_F", "C_man_1_3_F",
	"C_man_polo_1_F", "C_man_polo_2_F", "C_man_polo_3_F", "C_man_polo_4_F", "C_man_polo_5_F", "C_man_polo_6_F",
	"C_man_polo_1_F_euro", "C_man_polo_2_F_euro", "C_man_polo_4_F_euro", "C_man_polo_6_F_euro",
	"C_man_shorts_1_F", "C_man_shorts_2_F", "C_man_shorts_3_F", "C_man_shorts_4_F",
	"C_Man_casual_1_F", "C_Man_casual_2_F", "C_Man_casual_3_F", "C_Man_casual_4_F", "C_Man_casual_5_F", "C_Man_casual_6_F",
	"C_man_sport_1_F", "C_man_sport_2_F", "C_man_sport_3_F", "C_man_w_worker_F", "C_man_p_shorts_1_F"
];
private _vanTan = [
	"C_Man_casual_1_F_tanoan", "C_Man_casual_2_F_tanoan", "C_Man_casual_3_F_tanoan",
	"C_Man_casual_4_F_tanoan", "C_Man_casual_5_F_tanoan", "C_Man_casual_6_F_tanoan",
	"C_man_sport_1_F_tanoan", "C_man_sport_2_F_tanoan", "C_man_sport_3_F_tanoan"
];
private _vanEnoch = ["C_Man_1_enoch_F", "C_Man_2_enoch_F", "C_Man_3_enoch_F", "C_Man_4_enoch_F", "C_Man_5_enoch_F", "C_Man_6_enoch_F", "C_Farmer_01_enoch_F"];
private _vanEuro = ["C_man_polo_1_F_euro", "C_man_polo_2_F_euro", "C_man_polo_3_F_euro", "C_man_polo_4_F_euro", "C_man_polo_5_F_euro", "C_man_polo_6_F_euro", "C_Man_casual_1_F_euro", "C_Man_casual_2_F_euro", "C_Man_casual_3_F_euro"];

private _w = toLower worldName;
private _region = call {
	if ((_w find "chernarus") == 0 || {_w in ["utes", "woodland_acr", "bootcamp_acr", "bukovina", "bystrica"]}) exitWith {"este"};
	if (_w == "enoch") exitWith {"livonia"};
	if (_w in ["takistan", "zargabad", "shapur_baf", "mountains_acr", "desert_e"]) exitWith {"medio_oriente"};
	if (_w == "tanoa") exitWith {"tanoa"};
	"mediterraneo"
};
private _fnc_valid = {_this select {isClass (configFile >> "CfgVehicles" >> _x)}};
private _pool = switch (_region) do {
	case "este": {_cupCher call _fnc_valid};
	case "livonia": {(_cupCher + _vanEnoch + _vanEnoch + _vanEnoch) call _fnc_valid};
	case "medio_oriente": {_cupTK call _fnc_valid};
	case "tanoa": {_vanTan call _fnc_valid};
	default {_vanMed call _fnc_valid};
};
if (_pool isEqualTo [] && {_region in ["este", "livonia"]}) then {_pool = (_vanEnoch + _vanEuro) call _fnc_valid};
if (_pool isEqualTo []) then {_pool = _vanMed call _fnc_valid};
if (_pool isEqualTo []) exitWith {diag_log "VIOC_civilians: no hay clases de civiles validas; no hago nada."};
VIOC_CIVP_POOL = _pool;

//--- Pueblos elegibles (los de nombre militar/industrial quedan fuera)
VIOC_CIVP_TOWNS = CTI_Towns select {
	private _name = toLower (_x getVariable ["cti_town_name", ""]);
	(VIOC_CIVP_EXCLUDE findIf {(_name find _x) >= 0}) < 0
};

VIOC_CIVP_fnc_log = {
	diag_log ("VIOC_civilians: " + _this);
	if (VIOC_CIVP_DEBUG) then {systemChat ("[civiles] " + _this)};
};

//--- Todos los jugadores: deciden cuando se vacia un pueblo y desde donde no se debe ver aparecer a nadie
VIOC_CIVP_fnc_allPlayers = {
	(if (isMultiplayer) then {allPlayers - (entities "HeadlessClient_F")} else {[player]}) select {!isNull _x}
};
//--- Jugadores que llenan pueblos (no los que vuelan a mas de VIOC_CIVP_AIR_IGNORE m)
VIOC_CIVP_fnc_players = {
	(call VIOC_CIVP_fnc_allPlayers) select {((getPos (vehicle _x)) select 2) < VIOC_CIVP_AIR_IGNORE}
};

//--- [plantas bajas de casas, puntos de calle] del pueblo; se calcula al llenarlo
VIOC_CIVP_fnc_cache = {
	params ["_town"];
	private _cache = _town getVariable "vioc_civp_cache";
	if (!isNil "_cache") exitWith {_cache};
	private _center = getPosATL _town;
	private _radius = [220, 300] select ((_town getVariable ["cti_town_maxSV", 60]) >= 120);
	private _in = [];
	{
		if (alive _x) then {
			private _bp = _x buildingPos -1;
			if (_bp isNotEqualTo []) then {
				private _minZ = selectMin (_bp apply {_x select 2});
				{if ((_x select 2) < _minZ + 1.5) then {_in pushBack _x}} forEach _bp;
			};
		};
	} forEach (nearestTerrainObjects [_center, VIOC_CIVP_HOUSE_TYPES, _radius, false, true]);
	//--- puntos al costado de la calle, no sobre el asfalto (menos atropellos; los vehiculos IA no se frenan en el pueblo)
	private _out = [];
	{
		private _con = roadsConnectedTo _x;
		private _dir = if (_con isEqualTo []) then {random 360} else {_x getDir (_con select 0)};
		private _p = (getPosATL _x) getPos [4 + random 3, _dir + (selectRandom [90, -90])];
		if (!(isOnRoad _p) && {!(surfaceIsWater _p)}) then {_out pushBack _p};
	} forEach (_center nearRoads _radius);
	//--- tope de puntos para que las busquedas sigan siendo baratas en ciudades grandes
	if (count _in > 400) then {_in = (_in call BIS_fnc_arrayShuffle) select [0, 400]};
	if (count _out > 200) then {_out = (_out call BIS_fnc_arrayShuffle) select [0, 200]};
	_cache = [_in, _out];
	_town setVariable ["vioc_civp_cache", _cache];
	_cache
};

//--- true si algun jugador esta a < 80 m del punto o lo ve (a < 250 m)
VIOC_CIVP_fnc_seen = {
	params ["_p", "_players"];
	private _asl = (AGLToASL _p) vectorAdd [0, 0, 1.5];
	(_players findIf {
		private _d = _x distance2D _p;
		_d < 80 || {_d < 250 && {([vehicle _x, "VIEW", _x] checkVisibility [eyePos _x, _asl]) > 0.5}}
	}) >= 0
};

//--- Proximo destino: 40 % una casa, 60 % la calle, a menos de 160 m si se puede
VIOC_CIVP_fnc_pickDest = {
	params ["_u", "_town"];
	(_town getVariable ["vioc_civp_cache", [[], []]]) params ["_in", "_out"];
	private _list = if ((random 1 < 0.4 && {_in isNotEqualTo []}) || {_out isEqualTo []}) then {_in} else {_out};
	private _pos = getPosATL _u;
	private _near = _list select {(_x distance2D _pos) < 160};
	if (_near isEqualTo []) then {_near = _list};
	if (_near isEqualTo []) exitWith {_pos getPos [15 + random 30, random 360]};
	selectRandom _near
};

VIOC_CIVP_fnc_go = {
	params ["_u", "_town"];
	private _dest = [_u, _town] call VIOC_CIVP_fnc_pickDest;
	_u setVariable ["vioc_civp_dest", _dest];
	_u setVariable ["vioc_civp_state", "walk"];
	_u setVariable ["vioc_civp_next", time + 30 + random 60];
	_u setVariable ["vioc_civp_lp", getPosATL _u];
	_u setVariable ["vioc_civp_lpt", time];
	_u setDestination [_dest, "LEADER PLANNED", true];
};

//--- Escondite: la planta baja mas cercana (< 70 m) que no quede hacia el tirador
VIOC_CIVP_fnc_hidePos = {
	params ["_u", "_src"];
	private _town = _u getVariable ["vioc_civp_town", objNull];
	private _in = (_town getVariable ["vioc_civp_cache", [[], []]]) select 0;
	private _pos = getPosATL _u;
	private _from = if (isNull _src) then {_pos} else {getPosATL _src};
	private _dFrom = _pos distance2D _from;
	private _cand = _in select {(_x distance2D _pos) < 70 && {(_x distance2D _from) >= _dFrom}};
	if (_cand isEqualTo []) then {_cand = _in select {(_x distance2D _pos) < 70}};
	if (_cand isEqualTo []) exitWith {_pos getPos [30 + random 20, (_from getDir _pos) + random 60 - 30]};
	private _best = _cand select 0;
	private _bestD = 999999;
	{
		private _d = _x distance2D _pos;
		if (_d < _bestD) then {_bestD = _d; _best = _x};
	} forEach _cand;
	_best
};

//--- Reaccion a disparos cercanos / impactos / muerte de alguien al lado (corre aunque ya no haya peligro)
VIOC_CIVP_fnc_onDanger = {
	params ["_u", ["_src", objNull]];
	if (!alive _u || {(_u getVariable ["vioc_civp_panic", 0]) > time}) exitWith {};
	_u setVariable ["vioc_civp_panic", time + 40 + random 40];
	_u setVariable ["vioc_civp_state", "flee"];
	_u setVariable ["vioc_civp_next", time + 25];
	_u forceWalk false;
	_u setUnitPos "UP";
	private _dest = [_u, _src] call VIOC_CIVP_fnc_hidePos;
	_u setVariable ["vioc_civp_dest", _dest];
	_u setDestination [_dest, "LEADER PLANNED", true];
};

VIOC_CIVP_fnc_setup = {
	params ["_u", "_town"];
	_u setVariable ["vioc_civp_town", _town];
	_u setVariable ["vioc_civp_state", "idle"];
	_u setVariable ["vioc_civp_next", time + random 8];
	_u setVariable ["BIS_noCoreConversations", true];
	removeAllWeapons _u;
	{_u disableAI _x} forEach ["AUTOTARGET", "TARGET", "AUTOCOMBAT"];
	_u setDir (random 360);
	_u setBehaviour "CARELESS";
	_u forceWalk true;
	_u addEventHandler ["FiredNear", {_this call VIOC_CIVP_fnc_onDanger}];
	_u addEventHandler ["Hit", {_this call VIOC_CIVP_fnc_onDanger}];
	_u addEventHandler ["Killed", {
		params ["_dead", "_killer", "_instigator"];
		{
			if (alive _x && {!isNil {_x getVariable "vioc_civp_town"}}) then {[_x, _killer] call VIOC_CIVP_fnc_onDanger};
		} forEach (_dead nearEntities ["CAManBase", 40]);
		//--- Matar civiles baja el rating del que dispara o atropella. La mision recarga solo el del grupo del jugador y
		//--- el de los equipos IA (la copia de Chernarus otono, ninguno); un defensor, un mortero o el jugador sin recarga
		//--- quedaria renegado (sideEnemy). Se le devuelve el rating a 0 como minimo (solo unidades locales al servidor).
		private _who = [_killer, _instigator] select {!isNull _x};
		if (!isNull _killer) then {_who append (crew (vehicle _killer))};
		_who = (_who arrayIntersect _who) select {_x isKindOf "CAManBase" && {local _x}};
		if (_who isNotEqualTo []) then {
			_who spawn {
				{if (alive _x && {(rating _x) < 0}) then {_x addRating (0 - (rating _x))}} forEach _this;
				sleep 1;
				{if (alive _x && {(rating _x) < 0}) then {_x addRating (0 - (rating _x))}} forEach _this;
			};
		};
	}];
};

//--- Un paso (cada 5 s) de un civil vivo
VIOC_CIVP_fnc_tick = {
	params ["_u"];
	private _town = _u getVariable ["vioc_civp_town", objNull];
	private _state = _u getVariable ["vioc_civp_state", "idle"];
	private _next = _u getVariable ["vioc_civp_next", 0];
	private _arrived = (_u distance2D (_u getVariable ["vioc_civp_dest", getPosATL _u])) < 3;
	switch (_state) do {
		case "flee": {
			if (_arrived || {time > _next}) then {
				_u setUnitPos "MIDDLE";
				_u setVariable ["vioc_civp_state", "hide"];
			};
		};
		case "hide": {
			if (time > (_u getVariable ["vioc_civp_panic", 0])) then {
				_u setUnitPos "AUTO";
				_u forceWalk true;
				_u setVariable ["vioc_civp_state", "idle"];
				_u setVariable ["vioc_civp_next", time + 5 + random 10];
			};
		};
		case "walk": {
			if (_arrived) then {
				_u setVariable ["vioc_civp_state", "idle"];
				_u setVariable ["vioc_civp_next", time + 8 + random 30];
			} else {
				if ((_u distance2D (_u getVariable ["vioc_civp_lp", [0, 0, 0]])) > 1) then {
					_u setVariable ["vioc_civp_lp", getPosATL _u];
					_u setVariable ["vioc_civp_lpt", time];
				};
				//--- cambia de destino cada 30-90 s o si lleva 15 s atascado
				if (time > _next || {time - (_u getVariable ["vioc_civp_lpt", time]) > 15}) then {[_u, _town] call VIOC_CIVP_fnc_go};
			};
		};
		default {
			if (time > _next) then {[_u, _town] call VIOC_CIVP_fnc_go};
		};
	};
};

//--- Llena un pueblo; devuelve cuantos civiles creo (-1 = pueblo sin casas ni calles, no se vuelve a probar)
VIOC_CIVP_fnc_spawnTown = {
	params ["_town", "_budget"];
	([_town] call VIOC_CIVP_fnc_cache) params ["_in", "_out"];
	if ((count _in) < 4 && {(count _out) < 6}) exitWith {_town setVariable ["vioc_civp_skip", true]; -1};
	private _sv = _town getVariable ["cti_town_maxSV", 60];
	private _n = switch (true) do {case (_sv >= 120): {8}; case (_sv >= 90): {6}; default {4}};
	_n = round (_n * VIOC_CIVP_MULT);
	if (daytime < 5 || {daytime > 19}) then {_n = ceil (_n * VIOC_CIVP_NIGHT_MULT)};
	_n = _n min _budget;
	private _spawnList = if (_out isNotEqualTo []) then {_out} else {_in};
	private _players = call VIOC_CIVP_fnc_allPlayers;
	private _units = _town getVariable ["vioc_civp_units", []];
	for "_i" from 1 to _n do {
		private _pos = [];
		for "_t" from 1 to 8 do {
			private _p = selectRandom _spawnList;
			if !([_p, _players] call VIOC_CIVP_fnc_seen) exitWith {_pos = _p};
		};
		if (_pos isEqualTo []) exitWith {};
		private _u = createAgent [selectRandom VIOC_CIVP_POOL, _pos, [], 3, "NONE"];
		if (!isNull _u) then {
			[_u, _town] call VIOC_CIVP_fnc_setup;
			_units pushBack _u;
		};
		sleep 0.2;
	};
	_town setVariable ["vioc_civp_units", _units];
	_town setVariable ["vioc_civp_since", time];
	count _units
};

VIOC_CIVP_ACTIVE = [];
VIOC_CIVP_STATUS = [0, 0];
(format ["activo en %1 (%2): %3 de %4 pueblos elegibles, %5 clases, tope %6", worldName, _region, count VIOC_CIVP_TOWNS, count CTI_Towns, count VIOC_CIVP_POOL, VIOC_CIVP_CAP]) call VIOC_CIVP_fnc_log;

while {!CTI_GameOver} do {
	private _players = call VIOC_CIVP_fnc_players;
	private _allPlayers = call VIOC_CIVP_fnc_allPlayers;

	//--- 1) Vaciar los pueblos sin jugadores a menos de 1300 m (cuentan tambien los que vuelan alto)
	{
		private _town = _x;
		if (((_allPlayers findIf {(_x distance2D _town) < VIOC_CIVP_DESPAWN_DIST}) < 0) && {time - (_town getVariable ["vioc_civp_since", 0]) > VIOC_CIVP_MIN_LIFE}) then {
			{deleteVehicle _x} forEach (_town getVariable ["vioc_civp_units", []]);
			_town setVariable ["vioc_civp_units", nil];
			_town setVariable ["vioc_civp_cache", nil];
			VIOC_CIVP_ACTIVE set [_forEachIndex, objNull];
			(format ["vaciado: %1", _town getVariable ["cti_town_name", "?"]]) call VIOC_CIVP_fnc_log;
		};
	} forEach VIOC_CIVP_ACTIVE;
	VIOC_CIVP_ACTIVE = VIOC_CIVP_ACTIVE - [objNull];

	//--- 2) Mover a los civiles vivos
	private _alive = 0;
	{
		private _units = (_x getVariable ["vioc_civp_units", []]) select {!isNull _x};
		_x setVariable ["vioc_civp_units", _units];
		{
			if (alive _x) then {_alive = _alive + 1; [_x] call VIOC_CIVP_fnc_tick};
		} forEach _units;
	} forEach VIOC_CIVP_ACTIVE;

	//--- 3) Llenar los pueblos con un jugador a <= 900 m, el mas cercano primero, sin pasar el tope
	if (_players isNotEqualTo [] && {_alive < VIOC_CIVP_CAP}) then {
		private _pairs = [];
		{
			private _town = _x;
			if (!(_town in VIOC_CIVP_ACTIVE) && {!(_town getVariable ["vioc_civp_skip", false])}) then {
				private _d = selectMin (_players apply {_x distance2D _town});
				if (_d <= VIOC_CIVP_SPAWN_DIST) then {_pairs pushBack [_d, _forEachIndex]};
			};
		} forEach VIOC_CIVP_TOWNS;
		_pairs sort true;
		{
			if (_alive >= VIOC_CIVP_CAP) exitWith {};
			private _town = VIOC_CIVP_TOWNS select (_x select 1);
			private _n = [_town, VIOC_CIVP_CAP - _alive] call VIOC_CIVP_fnc_spawnTown;
			if (_n > 0) then {
				_alive = _alive + _n;
				VIOC_CIVP_ACTIVE pushBack _town;
				(format ["poblado: %1 (%2 civiles)", _town getVariable ["cti_town_name", "?"], _n]) call VIOC_CIVP_fnc_log;
			};
		} forEach _pairs;
	};

	VIOC_CIVP_STATUS = [count VIOC_CIVP_ACTIVE, _alive];
	sleep 5;
};

//--- Fin de partida: borrar todo
{
	{deleteVehicle _x} forEach (_x getVariable ["vioc_civp_units", []]);
} forEach VIOC_CIVP_ACTIVE;
VIOC_CIVP_ACTIVE = [];

